@r1 syntax.relation marker="on" from=$n2 to=$n3
@n3 syntax.nominal dependent="the" head="lake"
@c2 syntax.clause form=nonfinite verb="looking"
@r2 syntax.relation marker="toward" from=$c2 to=$n4
@n4 syntax.nominal dependent="the" head="boat"
@r3 syntax.relation marker="in" from=$n2 to=$n5
@n5 syntax.nominal dependent="the" head="picture"
@n6 syntax.nominal head="that"
@c3 syntax.clause form=declarative verb="is" subject=$n6
@c4 syntax.clause form=declarative modifier="how" verb="goes" subject=$n7
@n7 syntax.nominal dependent="the" head="picture"
@r4 syntax.relation from=$c1 to=$c3
@r5 syntax.relation from=$n2 to=$c2
@r6 syntax.relation from=$c3 to=$c4

sop:
@c1 syntax.clause form=imperative verb="let"
@n1 syntax.nominal dependent="a" head="duck"
@c2 syntax.clause form=nonfinite verb="face" subject=$n1 complement=$n2
@n2 syntax.nominal dependent="the" head="boat"
@r1 syntax.relation marker="on" from=$c2 to=$n3
@n3 syntax.nominal dependent="the" head="lake"
@c3 syntax.clause form=nonfinite verb="keeping" complement=$n4
@n4 syntax.nominal head="everything" dependent="else"
@c4 syntax.clause form=declarative modifier="where" verb="is" subject=$n5
@n5 syntax.nominal head="it"
@r2 syntax.relation from=$c1 to=$c2
@r3 syntax.relation from=$c2 to=$c3
@r4 syntax.relation from=$c3 to=$c4

alt:
@c1 syntax.clause form=imperative verb="let" complement=$n1
@n1 syntax.nominal dependent="a" head="duck"
@c2 syntax.clause form=nonfinite verb="face" subject=$n1 complement=$n2
@n2 syntax.nominal dependent="the" head="boat"
@r1 syntax.relation marker="on" from=$n2 to=$n3
